/**
 * Lifecycle of the shared reverse proxy. One container for the whole machine; each instance is
 * attached to it, never the other way round.
 */

import { isIPv4 } from 'node:net';
import { join } from 'node:path';
import { proxyAliases } from './services.mjs';
import { stateDirFor } from './compose.mjs';

export const PROXY_CONTAINER = 'urbo-proxy';

// Named distinctly from compose.mjs's own `COMPOSE_FILE` (the per-instance stack) — the two are
// easy to conflate since both modules talk to `docker compose`, but this one is the shared proxy's
// own, single compose file.
const PROXY_COMPOSE_FILE = 'backend/docker/proxy/docker-compose.proxy.yml';
const networkName = (instance) => `urbo-${instance}_default`;
const confName = (instance) => `urbo-${instance}.conf`;

// The single, fixed name `installNativeAndroidConf` writes under — never instance-scoped, because
// exactly one such file may exist at a time (see `render.mjs`'s `nativeAndroidNginxConf`). A later
// `just native android` overwrites this file rather than adding a second one alongside it.
export const NATIVE_ANDROID_CONF_NAME = 'native-android.conf';

/**
 * The shared hash-bucket tuning `render.mjs`'s `proxyTuningConf` generates. The `00-` prefix is
 * not decoration: `include conf.d/*.conf` loads in filename order, and nginx sizes a `map`'s hash
 * while it parses the block — so this has to be read before any instance conf.
 */
export const PROXY_TUNING_CONF_NAME = '00-tuning.conf';

const NGINX_IMAGE_DEFAULT_CONF_NAME = 'default.conf';

// Matches docker's own message for reconnecting a network the container is already a member of.
// Anything else (missing network, daemon error, misspelled network name, ...) is a real failure.
const ALREADY_CONNECTED = /already exists|already connected/i;

// Docker itself failing to remove a config that is already gone reads like this — a busybox `rm`
// (no `-f` semantics guaranteed inside the container) or a race with a concurrent teardown, not a
// reason to fail a repeat `just down`.
const NO_SUCH_FILE = /no such file/i;

// Docker's message for disconnecting a network the container is already off — the ordinary repeat
// teardown (e.g. `just down` run twice against a proxy that already dropped this instance), not a
// reason to fail. Two spellings, because the daemon has two paths into it: a running container
// that is simply not a member reads "is not connected to network <name>", while the path `-f`
// takes when the network itself no longer exists reads "is not connected to the network <name>".
// The second is what a `just fresh` meets after a `just fresh` that already ran `compose down -v`
// and then died before recreating anything. Anything else (a daemon error, a container mid-removal)
// is a real failure.
const NOT_CONNECTED = /is not connected to (?:the )?network/i;

export function connectArgs(instance) {
  const aliases = proxyAliases(instance).flatMap((alias) => ['--alias', alias]);
  return ['network', 'connect', ...aliases, networkName(instance), PROXY_CONTAINER];
}

/**
 * The single home for "what host port does the shared proxy currently publish" — both
 * `ensureProxy` below and `preflight.mjs`'s `checkProxyPort` need exactly this answer, and used to
 * carry two copies of the same `docker inspect` template kept in sync only by a comment.
 * A container with no port binding renders an error or an unparsable value (e.g. `<no value>`),
 * which we treat as "unknown", not as a crash — callers then treat that as a mismatch.
 *
 * The template ranges over every entry in `NetworkSettings.Ports` instead of indexing the literal
 * key `"80/tcp"`: the container now listens on whatever port was requested (`docker-compose.proxy.yml`
 * publishes `"<port>:<port>"`, not a fixed `<port>:80`), so the container-side port varies with
 * `URBO_PROXY_PORT` too and can no longer be hardcoded here. Exactly one binding is ever published,
 * so the range visits it exactly once.
 */
export async function publishedProxyPort({ exec }) {
  const inspect = await exec('docker', [
    'inspect',
    '-f',
    '{{range $port, $bindings := .NetworkSettings.Ports}}{{(index $bindings 0).HostPort}}{{end}}',
    PROXY_CONTAINER,
  ]);
  const stdout = inspect.stdout.trim();
  if (inspect.code === 0 && /^\d+$/.test(stdout)) {
    return Number(stdout);
  } else {
    return null;
  }
}

// The name `docker-compose.proxy.yml`'s `extra_hosts` maps to the host through `host-gateway`.
const HOST_GATEWAY_NAME = 'host.docker.internal';

/**
 * The IPv4 address `host.docker.internal` maps to inside the shared proxy — the one address the
 * dev-server blocks may proxy to (see `render.mjs`'s `upstreamTarget`).
 *
 * Asked of the proxy rather than left for nginx to resolve because the name has two addresses
 * there: Docker's `host-gateway` writes an IPv6 entry next to the IPv4 one (on Docker Desktop
 * `fdc4:f303:9324::254` beside `192.168.65.254`), and the proxy's networks have no IPv6 route. A
 * `proxy_pass` to the name became a two-peer upstream: every IPv6 attempt failed with "Network
 * unreachable" and took that peer out for 10 s, and a single slow connect on the IPv4 peer in that
 * window left no live upstream at all — 502 for every app/cms/boards request until it expired.
 * The resolver form the container blocks use (`ipv6=off`) is no way out: Docker's embedded DNS
 * never answers from `/etc/hosts`, the only place this name exists on a native Linux engine.
 *
 * `getent ahostsv4` is the same lookup nginx would make, restricted to IPv4. The result is
 * rendered in as a literal, so it is only as current as the last `just up` — it changes only with
 * the Docker daemon's own network settings (Docker Desktop's subnet, the Linux bridge's `bip`).
 * A proxy that is not running, or a name with no IPv4 entry, throws: there is no fallback address
 * that would not just move the 502 somewhere else.
 */
export async function hostGatewayIpv4({ exec }) {
  const lookup = await exec('docker', ['exec', PROXY_CONTAINER, 'getent', 'ahostsv4', HOST_GATEWAY_NAME]);
  // Each line starts with the address; `ahostsv4` lists the same one once per socket type.
  const address = lookup.code === 0 ? lookup.stdout.trim().split(/\s+/)[0] : '';
  if (isIPv4(address)) {
    return address;
  } else {
    throw new Error(
      `Could not read the shared proxy's IPv4 address for ${HOST_GATEWAY_NAME}: ` +
        `${lookup.stderr || lookup.stdout || 'no IPv4 entry'}`,
    );
  }
}
